from pathlib import Path
import zlib, base64
p=Path('index.html')
s=p.read_text()
start=s.index('function asciiText')
marker="$('#exportPdf').addEventListener('click',exportPdfFile);"
end=s.index(marker)+len(marker)
block=zlib.decompress(base64.b64decode('')).decode()
p.write_text(s[:start]+block+s[end:])
